import{_ as r,a0 as p,w as s,s as u,ao as l,I as i,x as n,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"CentOS 8 安裝圖解 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 8 安裝圖解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 8 安裝圖解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 8 安裝圖解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190927 CentOS 8 Installation Guide with Screenshots","title":"CentOS 8 安裝圖解","tag":"201910","desc":""},"relativePath":"201910/20190927 CentOS 8 Installation Guide with Screenshots.md","filePath":"[post].md"}'),c={name:"201910/20190927 CentOS 8 Installation Guide with Screenshots.md"};function d(w,t,h,S,m,C){const e=p("Link");return s(),u("div",null,[t[18]||(t[18]=l('<h1 id="centos-8-安裝圖解" tabindex="-1">CentOS 8 安裝圖解 <a class="header-anchor" href="#centos-8-安裝圖解" aria-label="Permalink to “CentOS 8 安裝圖解”">​</a></h1><p>繼 RHEL 8 發佈之後，CentOS 社區也發佈了讓人期待已久的 CentOS 8，併發布了兩種模式：</p><ul><li>CentOS stream：滾動發佈的 Linux 發行版，適用於需要頻繁更新的開發者</li><li>CentOS：類似 RHEL 8 的穩定操作系統，系統管理員可以用其部署或配置服務和應用</li></ul><p>在這篇文章中，我們會使用圖解的方式演示 CentOS 8 的安裝方法。</p><h3 id="centos-8-的新特性" tabindex="-1">CentOS 8 的新特性 <a class="header-anchor" href="#centos-8-的新特性" aria-label="Permalink to “CentOS 8 的新特性”">​</a></h3><ul><li>DNF 成為了默認的軟件包管理器，同時 yum 仍然是可用的</li><li>使用網絡管理器（<code>nmcli</code> 和 <code>nmtui</code>）進行網絡配置，移除了網絡腳本</li><li>使用 Podman 進行容器管理</li><li>引入了兩個新的包倉庫：BaseOS 和 AppStream</li><li>使用 Cockpit 作為默認的系統管理工具</li><li>默認使用 Wayland 作為顯示服務器</li><li><code>iptables</code> 將被 <code>nftables</code> 取代</li><li>使用 Linux 內核 4.18</li><li>提供 PHP 7.2、Python 3.6、Ansible 2.8、VIM 8.0 和 Squid 4</li></ul><h3 id="centos-8-所需的最低硬件配置" tabindex="-1">CentOS 8 所需的最低硬件配置: <a class="header-anchor" href="#centos-8-所需的最低硬件配置" aria-label="Permalink to “CentOS 8 所需的最低硬件配置:”">​</a></h3><ul><li>2 GB RAM</li><li>64 位 x86 架構、2 GHz 或以上的 CPU</li><li>20 GB 硬盤空間</li></ul><h3 id="centos-8-安裝圖解-1" tabindex="-1">CentOS 8 安裝圖解 <a class="header-anchor" href="#centos-8-安裝圖解-1" aria-label="Permalink to “CentOS 8 安裝圖解”">​</a></h3><h4 id="第一步-下載-centos-8-iso-文件" tabindex="-1">第一步：下載 CentOS 8 ISO 文件 <a class="header-anchor" href="#第一步-下載-centos-8-iso-文件" aria-label="Permalink to “第一步：下載 CentOS 8 ISO 文件”">​</a></h4>',10)),i("p",null,[t[1]||(t[1]=n("在 CentOS 官方網站 ",-1)),o(e,{href:"https://www.centos.org/download/"},{default:a(()=>[...t[0]||(t[0]=[n("https://www.centos.org/download/",-1)])]),_:1}),t[2]||(t[2]=n(" 下載 CentOS 8 ISO 文件。",-1))]),t[19]||(t[19]=l('<h4 id="第二步-創建-centos-8-啓動介質-usb-或-dvd" tabindex="-1">第二步： 創建 CentOS 8 啓動介質（USB 或 DVD） <a class="header-anchor" href="#第二步-創建-centos-8-啓動介質-usb-或-dvd" aria-label="Permalink to “第二步： 創建 CentOS 8 啓動介質（USB 或 DVD）”">​</a></h4><p>下載 CentOS 8 ISO 文件之後，將 ISO 文件燒錄到 USB 移動硬盤或 DVD 光盤中，作為啓動介質。</p><p>然後重啓系統，在 BIOS 中設置為從上面燒錄好的啓動介質啓動。</p><h4 id="第三步-選擇-安裝-centos-linux-8-0-選項" tabindex="-1">第三步：選擇“安裝 CentOS Linux 8.0”選項 <a class="header-anchor" href="#第三步-選擇-安裝-centos-linux-8-0-選項" aria-label="Permalink to “第三步：選擇“安裝 CentOS Linux 8.0”選項”">​</a></h4><p>當系統從 CentOS 8 ISO 啓動介質啓動之後，就可以看到以下這個界面。選擇“Install CentOS Linux 8.0”（安裝 CentOS Linux 8.0）選項並按回車。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Install-CentOS8.jpg" alt="Choose-Install-CentOS8"></p><h4 id="第四步-選擇偏好語言" tabindex="-1">第四步：選擇偏好語言 <a class="header-anchor" href="#第四步-選擇偏好語言" aria-label="Permalink to “第四步：選擇偏好語言”">​</a></h4><p>選擇想要在 CentOS 8 <strong>安裝過程</strong>中使用的語言，然後繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Language-CentOS8-Installation.jpg" alt="Select-Language-CentOS8-Installation"></p><h4 id="第五步-準備安裝-centos-8" tabindex="-1">第五步：準備安裝 CentOS 8 <a class="header-anchor" href="#第五步-準備安裝-centos-8" aria-label="Permalink to “第五步：準備安裝 CentOS 8”">​</a></h4><p>這一步我們會配置以下內容：</p><ul><li>鍵盤佈局</li><li>日期和時間</li><li>安裝來源</li><li>軟件選擇</li><li>安裝目標</li><li>Kdump</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Summary-CentOS8.jpg" alt="Installation-Summary-CentOS8"></p><p>如上圖所示，安裝嚮導已經自動提供了“<ruby>鍵盤佈局<rt>Keyboard</rt></ruby>”、“<ruby>時間和日期<rt>Time &amp; Date</rt></ruby>”、“<ruby>安裝來源<rt>Installation Source</rt></ruby>”和“<ruby>軟件選擇<rt>Software Selection</rt></ruby>”的選項。</p><p>如果你需要修改以上設置，點擊對應的圖標就可以了。例如修改系統的時間和日期，只需要點擊“<ruby>時間和日期<rt>Time &amp; Date</rt></ruby>”，選擇正確的時區，然後點擊“<ruby>完成<rt>Done</rt></ruby>”即可。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/TimeZone-CentOS8-Installation.jpg" alt="TimeZone-CentOS8-Installation"></p><p>在軟件選擇選項中選擇安裝的模式。例如“<ruby>包含圖形界面<rt>Server with GUI</rt></ruby>”選項會在安裝後的系統中提供圖形界面，而如果想安裝儘可能少的額外軟件，可以選擇“<ruby>最小化安裝<rt>Minimal Install</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Software-Selection-CentOS8-Installation.jpg" alt="Software-Selection-CentOS8-Installation"></p><p>這裏我們選擇“<ruby>包含圖形界面<rt>Server with GUI</rt></ruby>”，點擊“<ruby>完成<rt>Done</rt></ruby>”。</p><p>Kdump 功能默認是開啓的。儘管這是一個強烈建議開啓的功能，但也可以點擊對應的圖標將其關閉。</p><p>如果想要在安裝過程中對網絡進行配置，可以點擊“<ruby>網絡與主機名<rt>Network &amp; Host Name</rt></ruby>”選項。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Networking-During-CentOS8-Installation.jpg" alt="Networking-During-CentOS8-Installation"></p><p>如果系統連接到啓用了 DHCP 功能的調製解調器上，就會在啓動網絡接口的時候自動獲取一個 IP 地址。如果需要配置靜態 IP，點擊“<ruby>配置<rt>Configure</rt></ruby>”並指定 IP 的相關信息。除此以外我們還將主機名設置為 “linuxtechi.com”。</p><p>完成網絡配置後，點擊“<ruby>完成<rt>Done</rt></ruby>”。</p><p>最後我們要配置“<ruby>安裝目標<rt>Installation Destination</rt></ruby>”，指定 CentOS 8 將要安裝到哪一個硬盤，以及相關的分區方式。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Destination-Custom-CentOS8.jpg" alt="Installation-Destination-Custom-CentOS8"></p><p>點擊“<ruby>完成<rt>Done</rt></ruby>”。</p><p>如圖所示，我為 CentOS 8 分配了 40 GB 的硬盤空間。有兩種分區方案可供選擇：如果由安裝嚮導進行自動分區，可以從“<ruby>存儲配置<rt>Storage Configuration</rt></ruby>”中選擇“<ruby>自動<rt>Automatic</rt></ruby>”選項；如果想要自己手動進行分區，可以選擇“<ruby>自定義<rt>Custom</rt></ruby>”選項。</p><p>在這裏我們選擇“<ruby>自定義<rt>Custom</rt></ruby>”選項，並按照以下的方式創建基於 LVM 的分區：</p><ul><li><code>/boot</code> – 2 GB (ext4 文件系統)</li><li><code>/</code> – 12 GB (xfs 文件系統)</li><li><code>/home</code> – 20 GB (xfs 文件系統)</li><li><code>/tmp</code> – 5 GB (xfs 文件系統)</li><li>Swap – 1 GB (xfs 文件系統)</li></ul><p>首先創建 <code>/boot</code> 標準分區，設置大小為 2GB，如下圖所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/boot-partition-CentOS8-Installation.jpg" alt="boot-partition-CentOS8-Installation"></p><p>點擊“<ruby>添加掛載點<rt>Add mount point</rt></ruby>”。</p><p>再創建第二個分區 <code>/</code>，並設置大小為 12GB。點擊加號，指定掛載點和分區大小，點擊“<ruby>添加掛載點<rt>Add mount point</rt></ruby>”即可。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/slash-root-partition-centos8-installation.jpg" alt="slash-root-partition-centos8-installation"></p><p>然後在頁面上將 <code>/</code> 分區的分區類型從標準更改為 LVM，並點擊“<ruby>更新設置<rt>Update Settings</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Change-Partition-Type-CentOS8.jpg" alt="Change-Partition-Type-CentOS8"></p><p>如上圖所示，安裝嚮導已經自動創建了一個卷組。如果想要更改卷組的名稱，只需要點擊“<ruby>卷組<rt>Volume Group</rt></ruby>”標籤頁中的“<ruby>修改<rt>Modify</rt></ruby>”選項。</p><p>同樣地，創建 <code>/home</code> 分區和 <code>/tmp</code> 分區，分別將大小設置為 20GB 和 5GB，並設置分區類型為 LVM。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/home-partition-CentOS8-Installation.jpg" alt="home-partition-CentOS8-Installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/tmp-partition-centos8-installation.jpg" alt="tmp-partition-centos8-installation"></p><p>最後創建<ruby>交換分區<rt>Swap Partition</rt></ruby>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Swap-Partition-CentOS8-Installation.jpg" alt="Swap-Partition-CentOS8-Installation"></p><p>點擊“<ruby>添加掛載點<rt>Add mount point</rt></ruby>”。</p><p>在完成所有分區設置後，點擊“<ruby>完成<rt>Done</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Done-after-manual-partition-centos8.jpg" alt="Choose-Done-after-manual-partition-centos8"></p><p>在下一個界面，點擊“<ruby>應用更改<rt>Accept changes</rt></ruby>”，以上做的更改就會寫入到硬盤中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Accept-changes-CentOS8-Installation.jpg" alt="Accept-changes-CentOS8-Installation"></p><h4 id="第六步-選擇-開始安裝" tabindex="-1">第六步：選擇“開始安裝” <a class="header-anchor" href="#第六步-選擇-開始安裝" aria-label="Permalink to “第六步：選擇“開始安裝””">​</a></h4><p>完成上述的所有更改後，回到先前的安裝概覽界面，點擊“<ruby>開始安裝<rt>Begin Installation</rt></ruby>”以開始安裝 CentOS 8。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Begin-Installation-CentOS8.jpg" alt="Begin-Installation-CentOS8"></p><p>下面這個界面表示安裝過程正在進行中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-progress-centos8.jpg" alt="Installation-progress-centos8"></p><p>要設置 root 用户的口令，只需要點擊 “<ruby>root 口令<rt>Root Password</rt></ruby>”選項，輸入一個口令，然後點擊“<ruby>創建用户<rt>User Creation</rt></ruby>”選項創建一個本地用户。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Root-Password-CentOS8-Installation.jpg" alt="Root-Password-CentOS8-Installation"></p><p>填寫新創建的用户的詳細信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Local-User-Details-CentOS8.jpg" alt="Local-User-Details-CentOS8"></p><p>在安裝完成後，安裝嚮導會提示重啓系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-Installation-Progress.jpg" alt="CentOS8-Installation-Progress"></p><h4 id="第七步-完成安裝並重啓系統" tabindex="-1">第七步：完成安裝並重啓系統 <a class="header-anchor" href="#第七步-完成安裝並重啓系統" aria-label="Permalink to “第七步：完成安裝並重啓系統”">​</a></h4><p>安裝完成後要重啓系統。只需點擊“<ruby>重啓<rt>Reboot</rt></ruby>”按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Completed-CentOS8.jpg" alt="Installation-Completed-CentOS8"></p><p>注意：重啓完成後，記得要把安裝介質斷開，並將 BIOS 的啓動介質設置為硬盤。</p><h4 id="第八步-啓動新安裝的-centos-8-並接受許可協議" tabindex="-1">第八步：啓動新安裝的 CentOS 8 並接受許可協議 <a class="header-anchor" href="#第八步-啓動新安裝的-centos-8-並接受許可協議" aria-label="Permalink to “第八步：啓動新安裝的 CentOS 8 並接受許可協議”">​</a></h4><p>在 GRUB 引導菜單中，選擇 CentOS 8 進行啓動。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Grub-Boot-CentOS8.jpg" alt="Grub-Boot-CentOS8"></p><p>同意 CentOS 8 的許可證，點擊“<ruby>完成<rt>Done</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Accept-License-CentOS8-Installation.jpg" alt="Accept-License-CentOS8-Installation"></p><p>在下一個界面，點擊“<ruby>完成配置<rt>Finish Configuration</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Finish-Configuration-CentOS8-Installation.jpg" alt="Finish-Configuration-CentOS8-Installation"></p><h4 id="第九步-配置完成後登錄" tabindex="-1">第九步：配置完成後登錄 <a class="header-anchor" href="#第九步-配置完成後登錄" aria-label="Permalink to “第九步：配置完成後登錄”">​</a></h4><p>同意 CentOS 8 的許可證以及完成配置之後，會來到登錄界面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Login-screen-CentOS8.jpg" alt="Login-screen-CentOS8"></p><p>使用剛才創建的用户以及對應的口令登錄，按照提示進行操作，就可以看到以下界面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-Ready-Use-Screen.jpg" alt="CentOS8-Ready-Use-Screen"></p><p>點擊“<ruby>開始使用 CentOS Linux<rt>Start Using CentOS Linux</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Desktop-Screen-CentOS8.jpg" alt="Desktop-Screen-CentOS8"></p><p>以上就是 CentOS 8 的安裝過程，至此我們已經完成了 CentOS 8 的安裝。</p><p>歡迎給我們發送評論。</p><hr>',80)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),o(e,{href:"https://www.linuxtechi.com/centos-8-installation-guide-screenshots/"},{default:a(()=>[...t[3]||(t[3]=[n("https://www.linuxtechi.com/centos-8-installation-guide-screenshots/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=n("作者：",-1)),o(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[5]||(t[5]=[n("Pradeep Kumar",-1)])]),_:1}),t[10]||(t[10]=n(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[6]||(t[6]=[n("lujun9972",-1)])]),_:1}),t[11]||(t[11]=n(" 譯者：",-1)),o(e,{href:"https://github.com/HankChow"},{default:a(()=>[...t[7]||(t[7]=[n("HankChow",-1)])]),_:1}),t[12]||(t[12]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[n("Linux中國",-1)])]),_:1}),t[17]||(t[17]=n(" 榮譽推出",-1))])])}const y=r(c,[["render",d]]);export{g as __pageData,y as default};
